'use strict';

function nonEmpty(value) {
  return typeof value === 'string' && value.length > 0;
}

function buildAlert(options = {}) {
  if (options === null || typeof options !== 'object' || Array.isArray(options)) {
    throw new TypeError('options must be an object');
  }

  const title = options.title === undefined ? 'Operation failed' : options.title;
  const message = options.message === undefined ? 'Please try again.' : options.message;
  if (typeof title !== 'string' || typeof message !== 'string') {
    throw new TypeError('title and message must be strings');
  }

  let primary = null;
  if (options.primary !== undefined) {
    const value = options.primary;
    if (value === null || typeof value !== 'object' ||
        !nonEmpty(value.label) || !nonEmpty(value.action)) {
      throw new TypeError('invalid primary action');
    }
    primary = value;
  }

  const source = options.secondary === undefined ? [] : options.secondary;
  if (!Array.isArray(source)) throw new TypeError('secondary must be an array');
  const secondary = source.map((value) => {
    if (value === null || typeof value !== 'object' ||
        !nonEmpty(value.label) || !nonEmpty(value.target) ||
        (value.kind !== 'button' && value.kind !== 'link')) {
      throw new TypeError('invalid secondary action');
    }
    return { label: value.label, kind: value.kind, target: value.target };
  });

  return { role: 'alert', title, message, primary, secondary };
}

module.exports = { buildAlert };

