'use strict';
const assert = require('node:assert/strict');
const api = require('./solution');
assert.deepEqual(Object.keys(api), ['buildAlert']);
const { buildAlert } = api;

assert.deepEqual(buildAlert(), {
  role: 'alert',
  title: 'Operation failed',
  message: 'Please try again.',
  primary: null,
  secondary: []
});
assert.deepEqual(buildAlert({ title: '', message: '', ignored: 42 }), {
  role: 'alert', title: '', message: '', primary: null, secondary: []
});
for (const bad of [null, [], 'x', 1]) assert.throws(() => buildAlert(bad), TypeError);
assert.throws(() => buildAlert({ title: null }), TypeError);
assert.throws(() => buildAlert({ message: 3 }), TypeError);
assert.throws(() => buildAlert({ primary: null }), TypeError);
assert.throws(() => buildAlert({ primary: { label: '', action: 'retry' } }), TypeError);
assert.throws(() => buildAlert({ primary: { label: 'Retry', action: '' } }), TypeError);
assert.throws(() => buildAlert({ secondary: {} }), TypeError);
assert.throws(() => buildAlert({ secondary: [null] }), TypeError);
assert.throws(() => buildAlert({ secondary: [{ label: 'Help', kind: 'menu', target: '/help' }] }), TypeError);
assert.throws(() => buildAlert({ secondary: [{ label: '', kind: 'link', target: '/help' }] }), TypeError);
assert.throws(() => buildAlert({ secondary: [{ label: 'Help', kind: 'link', target: '' }] }), TypeError);

const options = {
  title: 'Failure',
  message: 'Choose an action',
  primary: { label: 'Retry', action: 'retry-now' },
  secondary: [
    { label: 'Details', kind: 'button', target: 'details' },
    { label: 'Support', kind: 'link', target: '/support' }
  ]
};
const result = buildAlert(options);
assert.deepEqual(result, {
  role: 'alert',
  title: 'Failure',
  message: 'Choose an action',
  primary: { label: 'Retry', action: 'retry-now' },
  secondary: [
    { label: 'Details', kind: 'button', target: 'details' },
    { label: 'Support', kind: 'link', target: '/support' }
  ]
});
assert.notStrictEqual(result.primary, options.primary);
assert.notStrictEqual(result.secondary, options.secondary);
assert.notStrictEqual(result.secondary[0], options.secondary[0]);
options.primary.label = 'Changed';
options.secondary[0].label = 'Changed';
options.secondary.push({ label: 'Extra', kind: 'link', target: '/extra' });
assert.equal(result.primary.label, 'Retry');
assert.equal(result.secondary[0].label, 'Details');
assert.equal(result.secondary.length, 2);
result.primary.action = 'changed';
result.secondary[1].target = 'changed';
const fresh = buildAlert({ primary: { label: 'Retry', action: 'retry-now' }, secondary: [{ label: 'Support', kind: 'link', target: '/support' }] });
assert.equal(fresh.primary.action, 'retry-now');
assert.equal(fresh.secondary[0].target, '/support');

